mapper.select:
SELECT count(*) FROM (
    SELECT id FROM dataset WHERE NOT is_deleted AND default_time_dimension_id=#{id}
    UNION ALL SELECT id FROM dataset_field WHERE NOT is_deleted AND dataset_id=#{id}
    UNION ALL SELECT id FROM dimension WHERE NOT is_deleted AND (dataset_id=#{id} OR dataset_field_id=#{id})
    UNION ALL SELECT id FROM metric WHERE NOT is_deleted AND (dataset_id=#{id} OR dataset_field_id=#{id} OR default_time_dimension_id=#{id})
    UNION ALL SELECT id FROM dataset_relationship WHERE NOT is_deleted AND (source_dataset_id=#{id} OR target_dataset_id=#{id})
    UNION ALL SELECT p.relationship_id FROM dataset_relationship_field_pair p JOIN dataset_relationship r ON r.id=p.relationship_id
        WHERE NOT r.is_deleted AND (p.source_field_id=#{id} OR p.target_field_id=#{id})
) dependency WHERE NOT EXISTS (SELECT 1 FROM git_object_ownership o WHERE o.object_id=dependency.id AND o.repository_id=#{repositoryId})
